mapper.select:

SELECT EXISTS(SELECT 1 FROM () original
  WHERE original.binding=#{row.binding} AND original.binding_id=#{row.bindingId}
    AND original.task_id <=> #{row.taskId} AND original.domain=#{row.domain} AND original.target_id=#{row.targetId}
    AND original.target_version_id <=> #{row.targetVersionId}
    AND original.target_version_number <=> #{row.targetVersionNumber}
    AND original.target_revision <=> #{row.targetRevision}
    AND BINARY original.target_title=BINARY #{row.targetTitle})



    SELECT excerpt_id,ordinal FROM ai_material_draft_source WHERE owner_id=#{owner} AND task_id=#{taskId}


    SELECT excerpt_id,ordinal FROM ai_fact_draft_material WHERE owner_id=#{owner} AND task_id=#{taskId}


    SELECT excerpt_id,ordinal FROM ai_relation_evidence_material WHERE owner_id=#{owner} AND task_id=#{taskId}

  SELECT NULL AS excerpt_id,NULL AS ordinal WHERE 1=0

ORDER BY ordinal LIMIT #{limit}

choose.when:
SELECT 'PREPARATION' AS domain,i.id,v.id AS version_id,v.version_number,i.revision,i.status,v.title
FROM preparation_item i LEFT JOIN preparation_version v ON v.owner_id=i.owner_id AND v.item_id=i.id AND v.id=i.current_version_id
WHERE i.owner_id=#{owner} AND i.id=#{targetId}

SELECT 'QUESTION' AS domain,i.id,v.id AS version_id,v.version_number,i.revision,i.status,v.title
FROM question i LEFT JOIN question_version v ON v.owner_id=i.owner_id AND v.question_id=i.id AND v.id=i.current_version_id
WHERE i.owner_id=#{owner} AND i.id=#{targetId}

SELECT 'KNOWLEDGE' AS domain,i.id,v.id AS version_id,v.version_number,i.metadata_revision AS revision,i.status,v.title
FROM knowledge_item i LEFT JOIN knowledge_version v ON v.owner_id=i.owner_id AND v.item_id=i.id AND v.id=i.current_version_id
WHERE i.owner_id=#{owner} AND i.id=#{targetId}

mapper.select:
SELECT * FROM material_dependency_impact WHERE owner_id=#{owner} AND excerpt_id=#{excerptId}
AND revision=0
AND (created_at < #{beforeTime} OR (created_at=#{beforeTime} AND id < #{beforeId}))
ORDER BY created_at DESC,id DESC LIMIT #{limit}

mapper.update:
UPDATE material_dependency_impact SET revision=1,choice=#{request.choice},reason=#{request.reason},
  resolution_target_version_id=#{request.expectedTargetVersionId},resolution_target_revision=#{request.expectedTargetRevision},decided_at=#{now}
WHERE owner_id=#{owner} AND id=#{impactId} AND revision=#{request.expectedRevision} AND revision=0

mapper.select:
SELECT excerpt_id FROM (
  SELECT r.excerpt_id FROM preparation_material_reference r
  WHERE r.owner_id=#{owner} AND r.item_id=#{itemId} AND r.version_id=#{versionId}
  UNION
  SELECT m.excerpt_id FROM ai_fact_draft_decision d
  JOIN preparation_version adopted ON adopted.owner_id=d.owner_id AND adopted.item_id=d.target_item_id AND adopted.id=d.target_version_id
  JOIN preparation_version selected ON selected.owner_id=d.owner_id AND selected.item_id=d.target_item_id AND selected.id=#{versionId}
  JOIN ai_fact_draft_material m ON m.owner_id=d.owner_id AND m.task_id=d.task_id
  WHERE d.owner_id=#{owner} AND d.target_item_id=#{itemId} AND d.status='ADOPTED'
    AND selected.version_number>=adopted.version_number
) sources ORDER BY excerpt_id LIMIT #{limit}

choose.when:
SELECT EXISTS(SELECT 1 FROM preparation_version old JOIN preparation_version latest
  ON latest.owner_id=old.owner_id AND latest.item_id=old.item_id AND latest.id=#{currentVersionId}
  WHERE old.owner_id=#{owner} AND old.item_id=#{targetId} AND old.id=#{previousVersionId}
    AND latest.version_number>old.version_number
    AND BINARY JSON_REMOVE(CAST(latest.content_json AS JSON),'$.title')
      <>BINARY JSON_REMOVE(CAST(old.content_json AS JSON),'$.title'))

SELECT EXISTS(SELECT 1 FROM question_version old JOIN question_version latest
  ON latest.owner_id=old.owner_id AND latest.question_id=old.question_id AND latest.id=#{currentVersionId}
  WHERE old.owner_id=#{owner} AND old.question_id=#{targetId} AND old.id=#{previousVersionId}
    AND latest.version_number>old.version_number
    AND BINARY JSON_REMOVE(CAST(latest.prompt_json AS JSON),'$.title')
      <>BINARY JSON_REMOVE(CAST(old.prompt_json AS JSON),'$.title'))

SELECT EXISTS(SELECT 1 FROM knowledge_version old JOIN knowledge_version latest
  ON latest.owner_id=old.owner_id AND latest.item_id=old.item_id AND latest.id=#{currentVersionId}
  WHERE old.owner_id=#{owner} AND old.item_id=#{targetId} AND old.id=#{previousVersionId}
    AND latest.version_number>old.version_number AND BINARY latest.body<>BINARY old.body)
